all.fixed_definition:
all(arr)::
  assert std.isArray(arr) : 'all() parameter should be an array, got ' + std.type(arr);
  local arrLen = std.length(arr);
  local aux(idx) =
    if idx >= arrLen then
      true
    else
      local e = arr[idx];
      assert std.isBoolean(e) : 'element "%s" of type %s is not a boolean' % [e, std.type(e)];
      if !e then
        false
      else
        aux(idx + 1) tailstrict;
  aux(0),

