any.fixed_definition:
any(arr)::
  assert std.isArray(arr) : 'any() parameter should be an array, got ' + std.type(arr);
  local arrLen = std.length(arr);
  local aux(idx) =
    if idx >= arrLen then
      false
    else
      local e = arr[idx];
      assert std.isBoolean(e) : 'element "%s" of type %s is not a boolean' % [e, std.type(e)];
      if e then
        true
      else
        aux(idx + 1) tailstrict;
  aux(0),

